mapper.select:
SELECT st.approve_status AS tabFlag, count(distinct st.id) AS count FROM stocktaking_task st WHERE st.is_deleted=FALSE
${permissionSql}
GROUP BY st.approve_status

SELECT st.id, st.code, st.source_code AS sourceCode, st.source_id AS sourceId, st.approve_status AS approveStatus, st.create_time AS createTime, st.create_user_name AS createUserName, sp.mode AS stocktakingMode, sp.type AS stocktakingType, sp.separate_rule AS separateRule, st.status AS stocktakingStatus, st.approve_user_name AS approveUserName, st.bill_date as billDate FROM stocktaking_task st LEFT JOIN stocktaking_plan sp ON st.source_id=sp.id AND sp.is_deleted=FALSE LEFT JOIN stocktaking_task_detail std on std.main_id = st.id and std.is_deleted = FALSE WHERE ${params.sqlMap.default} and st.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
st.id DESC

SELECT st.id, st.code, st.source_code AS sourceCode, st.source_id AS sourceId, st.approve_status AS approveStatus, st.create_time AS createTime, st.create_user_name AS createUserName, sp.mode AS stocktakingMode, sp.type AS stocktakingType, st.status AS stocktakingStatus, sp.separate_rule AS separateRule, st.approve_user_name AS approveUserName FROM stocktaking_task st LEFT JOIN stocktaking_plan sp ON st.source_id=sp.id AND sp.is_deleted=FALSE WHERE ${params.sqlMap.default} and st.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
st.id DESC

SELECT st.id, st.code, std.sku_no, std.qty FROM stocktaking_task st INNER JOIN stocktaking_task_detail std ON st.id=std.main_id AND std.is_deleted=FALSE WHERE st.is_deleted=FALSE AND qty=0
AND st.id IN
#{id}
